∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {Cl : Breakdown.CellCert.CellAnalysis.CellClasses} {rowSet : Finset (Fin N)}
  {F : Breakdown.CellCert.CellFormula.CellFormulaInputs k N S},
  Breakdown.CellCert.CellFormula.IsFormulaInputs α c K S B Cl rowSet F →
    ∀ (x : Breakdown.CellCert.Assembly.FieldTuple k),
      Breakdown.CellCert.Assembly.IsAdmissible c x →
        F.coordToData (Sum.elim (F.skeleton x) (F.interior x)) = F.trueData x

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {Cl : Breakdown.CellCert.CellAnalysis.CellClasses} {rowSet : Finset (Fin N)}
  {F : Breakdown.CellCert.CellFormula.CellFormulaInputs k N S},
  Breakdown.CellCert.CellFormula.IsFormulaInputs α c K S B Cl rowSet F → IsLinearMap ℝ F.coordToData

∀ {N k slots : ℕ} {box : Breakdown.CellCert.CellAnalysis.CellBox}
  {scalars : Breakdown.CellCert.CellAnalysis.CellScalars} {bases : Breakdown.CellCert.CellAnalysis.CellBases}
  {classes : Breakdown.CellCert.CellAnalysis.CellClasses} {rows : Breakdown.CellCert.CellAnalysis.CellRows N slots k}
  {coords : Breakdown.CellCert.CellCoordinates.CellCoords k slots} {box_1 : Breakdown.CellCert.CellAnalysis.CellBox}
  {scalars_1 : Breakdown.CellCert.CellAnalysis.CellScalars} {bases_1 : Breakdown.CellCert.CellAnalysis.CellBases}
  {classes_1 : Breakdown.CellCert.CellAnalysis.CellClasses}
  {rows_1 : Breakdown.CellCert.CellAnalysis.CellRows N slots k}
  {coords_1 : Breakdown.CellCert.CellCoordinates.CellCoords k slots},
  { box := box, scalars := scalars, bases := bases, classes := classes, rows := rows, coords := coords } =
      { box := box_1, scalars := scalars_1, bases := bases_1, classes := classes_1, rows := rows_1,
        coords := coords_1 } →
    box = box_1 ∧ scalars = scalars_1 ∧ bases = bases_1 ∧ classes = classes_1 ∧ rows = rows_1 ∧ coords = coords_1

∀ (z z' : Breakdown.Space),
  { re := z.ofLp 0, im := z.ofLp 1 } - { re := z'.ofLp 0, im := z'.ofLp 1 } =
    { re := (z - z').ofLp 0, im := (z - z').ofLp 1 }

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {S : Breakdown.CellCert.Assembly.CellSplit k N}
  {K₂ : Fin S.cellCount} {r : Breakdown.CellCert.FinalChain.CellEntry N k S.slots},
  Breakdown.CellCert.FinalChain.IsCellFacts α c S K₂ r → S.cell K₂ =ᵐ[MeasureTheory.volume] r.box.solid

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {S : Breakdown.CellCert.Assembly.CellSplit k N}
  {K₂ : Fin S.cellCount} {r : Breakdown.CellCert.FinalChain.CellEntry N k S.slots},
  Breakdown.CellCert.FinalChain.IsCellFacts α c S K₂ r → ∀ (a : Fin N), S.rowCell a = K₂ ↔ a ∈ r.rows.rowSet

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {Cl : Breakdown.CellCert.CellAnalysis.CellClasses} {rowSet : Finset (Fin N)}
  {F : Breakdown.CellCert.CellFormula.CellFormulaInputs k N S},
  Breakdown.CellCert.CellFormula.IsFormulaInputs α c K S B Cl rowSet F →
    ∀ (x : Breakdown.CellCert.Assembly.FieldTuple k),
      Breakdown.CellCert.Assembly.IsAdmissible c x →
        ∀ (ζ : Fin k → ℝ),
          Breakdown.CellCert.CellFormula.quadFormValue F.localForm (F.dataVec (F.trueData x) x.2.2.2.1 ζ) ≤
            Breakdown.CellCert.CellAnalysis.CellScalars.localCellForm c K S Cl x.2.2.2.1 ζ x.1 x.2.1 x.2.2.1

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {Cl : Breakdown.CellCert.CellAnalysis.CellClasses} {rowSet : Finset (Fin N)}
  {F : Breakdown.CellCert.CellFormula.CellFormulaInputs k N S},
  Breakdown.CellCert.CellFormula.IsFormulaInputs α c K S B Cl rowSet F →
    ∀ (x : Breakdown.CellCert.Assembly.FieldTuple k),
      Breakdown.CellCert.Assembly.IsAdmissible c x →
        ∀ a ∈ rowSet,
          Breakdown.CellCert.CellAnalysis.CellScalars.lowRowValue c K S α x a = F.rowValue a (F.trueData x) x.2.2.2.1

∀ {α : ℝ} {k N : ℕ} {c : Breakdown.CellCert.FracCellData k N} {K : Breakdown.CellCert.CellAnalysis.CellBox}
  {S : Breakdown.CellCert.CellAnalysis.CellScalars} {B : Breakdown.CellCert.CellAnalysis.CellBases}
  {Cl : Breakdown.CellCert.CellAnalysis.CellClasses} {rowSet : Finset (Fin N)}
  {F : Breakdown.CellCert.CellFormula.CellFormulaInputs k N S},
  Breakdown.CellCert.CellFormula.IsFormulaInputs α c K S B Cl rowSet F →
    ∀ (x : Breakdown.CellCert.Assembly.FieldTuple k),
      Breakdown.CellCert.Assembly.IsAdmissible c x →
        ∀ (i : Breakdown.CellCert.CellFormula.LowSupp S),
          (F.lowEntry i).elim 0 (F.trueData x) = Breakdown.CellCert.CellAnalysis.CellScalars.lowCoef c K S B x ↑i
